// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }

    function testFuzz_property(address actor, uint256 amount) public {
        amount = bound(amount, 0, 1 ether);
        vm.assume(actor != address(0));

        vm.deal(actor, amount);

        vm.prank(actor);
        c.addToBalance{value: amount}();

        uint bal_for_actor = c.getBalance(actor);
        uint bal_zero = c.getBalance(address(0));

        assertTrue(bal_for_actor == amount);
    }
}
